#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Release-Wizard für atvprep: führt durch docs/releasing.md, vom Versionsvorschlag bis zum
# veröffentlichten GitHub-Release samt Gitea-Spiegel. Aufruf: ./scripts/release-wizard.sh
# Ein abgebrochener Lauf kann neu gestartet werden; erledigte Schritte werden erkannt und
# übersprungen, die gewählte Version merkt sich der Wizard in .git/release-wizard.env.

KEY="$HOME/.ssh/atvprep-release-ed25519"
NAMES=(release.json release.json.sig release.pub atvprep-linux-x86_64 atvprep-linux-aarch64)
SEMVER='^[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z.]+)?$'

die() { warn "$1"; note "Ursache beheben und den Wizard neu starten; erledigte Schritte werden übersprungen."; exit 1; }
# run CMD… shows and runs CMD, then restores the terminal settings: a child that leaves the
# terminal in raw mode (ffmpeg with the terminal as stdin does) would swallow Enter at the next pause.
run() {
  local tty_state="" rc=0
  [[ -t 0 ]] && tty_state=$(stty -g 2>/dev/null || true)
  printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"
  "$@" || rc=$?
  if [[ -n "$tty_state" ]]; then stty "$tty_state" 2>/dev/null || true; fi
  return "$rc"
}

cargo_version() { sed -n '/^\[workspace.package\]/,/^\[/{s/^version = "\([^"]*\)"/\1/p;}' rust/Cargo.toml; }

# tracked_changes lists modified tracked files; untracked files do not reach the build.
tracked_changes() { git status --porcelain --untracked-files=no; }

# pr_merges prints "<merge-sha> <pr-number>" for every PR merged into main since LAST_TAG.
pr_merges() {
  git log --first-parent --merges --format='%H %s' "$LAST_TAG..HEAD" |
    sed -nE 's/^([0-9a-f]+) Merge pull request #([0-9]+) .*/\1 \2/p'
}

# commit_lines prints "<subject>\t<pr>" for every change since LAST_TAG: commits of each merged
# PR, then commits made directly on main (without the wizard's own release commits).
commit_lines() {
  local sha pr
  while read -r sha pr; do
    git log --no-merges --format="%s%x09$pr" "$sha^1..$sha^2"
  done < <(pr_merges)
  git log --first-parent --no-merges --format='%s%x09' "$LAST_TAG..HEAD" |
    grep -Ev '^chore: (Version [0-9]|signiertes Release-Manifest)' || true
}

# breaking_count counts commits marked as breaking: `typ!:` in the subject or a
# BREAKING CHANGE footer in the body, in PR commits and PR descriptions.
breaking_count() {
  local sha pr n=0
  n=$(commit_lines | cut -f1 | grep -cE '^[a-z]+(\([a-z0-9-]+\))?!: ' || true)
  while read -r sha pr; do
    if git log --no-merges --format=%B "$sha^1..$sha^2" | grep -qE '^BREAKING[ -]CHANGE'; then n=$((n + 1)); fi
    if gh pr view "$pr" --json title,body --jq '.title + "\n" + .body' 2>/dev/null |
      grep -qE '^([a-z]+(\([a-z0-9-]+\))?!: |BREAKING[ -]CHANGE)'; then n=$((n + 1)); fi
  done < <(pr_merges)
  echo "$n"
}

# suggest_version LAST BREAKING FEATS FIXES: 0.x counts a break as minor and everything else
# as patch (bisherige Praxis); from 1.0 on plain SemVer.
suggest_version() {
  local major minor patch
  IFS=. read -r major minor patch <<<"${1%%-*}"
  if (( major == 0 )); then
    if (( $2 > 0 )); then echo "0.$((minor + 1)).0"; else echo "0.$minor.$((patch + 1))"; fi
  elif (( $2 > 0 )); then echo "$((major + 1)).0.0"
  elif (( $3 > 0 )); then echo "$major.$((minor + 1)).0"
  else echo "$major.$minor.$((patch + 1))"; fi
}

# draft_notes VERSION writes the release notes draft from the commits since LAST_TAG.
draft_notes() {
  local v="$1" prs lines
  prs=$(pr_merges | awk '{printf "%s#%s", (NR > 1 ? ", " : ""), $2}')
  lines=$(commit_lines | awk -F'\t' '!seen[$1]++')
  section() { # <regex> <heading>
    local body
    body=$(grep -E "^$1" <<<"$lines" | sed -E 's/^[a-z]+(\([a-z0-9-]+\))?!?: //' |
      awk -F'\t' '{ print "- " toupper(substr($1,1,1)) substr($1,2) ($2 != "" ? " (#" $2 ")" : "") }' || true)
    [[ -n "$body" ]] && printf '## %s\n\n%s\n\n' "$2" "$body"
    return 0
  }
  {
    printf '<!-- ENTWURF: aus den Commits seit %s erzeugt. Für den Betreiber umschreiben (nach Thema\n' "$LAST_TAG"
    printf '     gruppieren, Begriffe aus GLOSSARY.md, Vorbild docs/release-notes/0.6.0.md), dann diesen\n'
    printf '     Kommentar löschen. Der Wizard fährt erst ohne ihn fort. -->\n\n'
    printf '# Version %s\n\n' "$v"
    printf 'Hinweise für den Betreiber zu diesem Release. Begriffe: `GLOSSARY.md`.%s\n\n' "${prs:+ PRs: $prs.}"
    section '[a-z]+(\([a-z0-9-]+\))?!: ' 'Achtung: nicht abwärtskompatibel'
    section 'feat(\([a-z0-9-]+\))?: ' 'Neu'
    section '(fix|perf)(\([a-z0-9-]+\))?: ' 'Behoben'
    printf '## Nicht betroffen\n\n- Kein Datenbank-Update nötig. <!-- prüfen -->\n'
  } > "docs/release-notes/$v.md"
}

# ── KI-Hilfe über die Claude-CLI ─────────────────────────────────────────
# Haiku prüft auf nicht markierte Brüche, Sonnet formuliert die Release-Hinweise. Mehr als Sonnet
# ist nicht zugelassen. RELEASE_AI=0 schaltet beides ab; RELEASE_MODEL_CHECK und
# RELEASE_MODEL_NOTES wählen ein anderes Modell innerhalb dieser Grenze.
MODEL_CHECK=${RELEASE_MODEL_CHECK:-haiku}
MODEL_NOTES=${RELEASE_MODEL_NOTES:-sonnet}

ai_ready() { [[ "${RELEASE_AI:-1}" != 0 ]] && command -v claude >/dev/null 2>&1; }

# ai MODEL BUDGET_USD < prompt: one answer without tools, outside the repo so no project
# instructions or hooks apply.
ai() {
  case "$1" in haiku | sonnet | claude-haiku-* | claude-sonnet-*) ;;
    *) warn "Modell $1 ist nicht zugelassen (höchstens Sonnet)."; return 1 ;;
  esac
  local dir rc=0
  dir=$(mktemp -d)
  (cd "$dir" && claude -p --model "$1" --tools "" --no-session-persistence --max-budget-usd "$2") || rc=$?
  rm -rf "$dir"
  return "$rc"
}

# change_context prints what changed since LAST_TAG: PRs with description and commits, direct
# commits, new migrations.
change_context() {
  local sha pr
  while read -r sha pr; do
    printf '\n### PR #%s: %s\n' "$pr" "$(gh pr view "$pr" --json title --jq .title 2>/dev/null)"
    gh pr view "$pr" --json body --jq .body 2>/dev/null | head -c 3000 || true
    printf '\nCommits:\n'
    git log --no-merges --format='- %s' "$sha^1..$sha^2"
  done < <(pr_merges)
  printf '\n### Direkt auf main\n'
  git log --first-parent --no-merges --format='- %s' "$LAST_TAG..HEAD" |
    grep -Ev '^- chore: (Version [0-9]|signiertes Release-Manifest)' || true
  printf '\n### Neue Datenbank-Migrationen\n'
  git diff --diff-filter=A --name-only "$LAST_TAG..HEAD" -- rust/crates/atvprep-manager/src/migrations || true
}

# ai_breaking prints "BRUCH: ja|nein" and up to five reasons.
ai_breaking() {
  {
    cat <<'EOF'
Du prüfst ein Release von atvprep (Rust-Dienst mit HTTP-API unter /api/v1, CLI und Weboberfläche)
auf Änderungen, die nicht abwärtskompatibel sind: entfernte oder umbenannte API-Pfade,
Parameter oder Felder, neue Ablehnungen (422/404) für bisher gültige Aufrufe, geänderte
CLI-Befehle oder Konfigurationsschlüssel, Migrationen, die bestehende Daten umdeuten. Interne
Refactorings, Tests und reine UI-Änderungen zählen nicht.
Antworte auf Deutsch, ohne Einleitung, genau in diesem Format:
BRUCH: ja|nein
- <Grund mit PR-Nummer, höchstens fünf Zeilen; bei "nein" höchstens eine>
EOF
    printf '\n## Änderungen seit %s\n' "$LAST_TAG"
    change_context
    printf "\n## Neue Migrationen (SQL)\n"
    git diff --diff-filter=A "$LAST_TAG..HEAD" -- rust/crates/atvprep-manager/src/migrations | head -c 30000 || true
    printf '\n## Diff der API (gekürzt)\n'
    git diff "$LAST_TAG..HEAD" -- rust/crates/atvprep-api ':!*tests*' | head -c 120000 || true
  } | ai "$MODEL_CHECK" 0.50
}

# ai_notes VERSION < mechanical draft: operator-facing release notes in the style of the last ones.
ai_notes() {
  local example
  example=$(printf "%s\n" docs/release-notes/*.md | grep -vF "/$1.md" | sort -V | tail -1)
  {
    cat <<EOF
Schreibe die Release-Hinweise für atvprep $1 als Markdown, auf Deutsch, für den Betreiber
(nicht für Entwickler). Halte dich an Aufbau und Ton des Vorbilds: Titel "# Version $1", ein
Einleitungssatz mit den PR-Nummern, dann Abschnitte nach Thema statt nach Commit-Typ, knappe
Stichpunkte, die das sichtbare Verhalten beschreiben. Interne Refactorings, Tests und CI nur
erwähnen, wenn sie für den Betrieb zählen. Wenn sich die API ändert, einen Abschnitt
"## Änderungen an der API"; zum Schluss "## Nicht betroffen" (Datenbank-Update nötig oder nicht:
neue Migrationen sind unten aufgeführt). Begriffe exakt wie im Glossar. Nichts erfinden: was
sich aus dem Material nicht ergibt, weglassen. Gib nur das Markdown aus, ohne Codeblock-Zaun.
EOF
    printf '\n## Vorbild (%s)\n\n' "$example"; cat "$example"
    printf '\n## Glossar\n\n'; cat GLOSSARY.md
    printf '\n## Einschätzung zu Brüchen\n\n%s\n' "${AI_BREAKING:-keine}"
    printf '\n## Änderungen seit %s\n' "$LAST_TAG"; change_context
    printf '\n## Mechanischer Entwurf aus den Commit-Betreffs\n\n'; cat
  } | ai "$MODEL_NOTES" 1.00
}

edit_notes() {
  local file="$1"
  "${VISUAL:-${EDITOR:-vi}}" "$file"
  while grep -q 'ENTWURF' "$file"; do
    warn "$file enthält noch den ENTWURF-Kommentar."
    confirm "Nochmals im Editor öffnen?" || die "Release-Hinweise noch nicht fertig."
    "${VISUAL:-${EDITOR:-vi}}" "$file"
  done
}

run_wizard() {

TOTAL_STAGES=11
cd "$(git rev-parse --show-toplevel)"
ENV_FILE="$(git rev-parse --absolute-git-dir)/release-wizard.env"

banner "atvprep: neues Release"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Vorprüfung"
say "Prüft Zweig, Arbeitsbaum, Stand gegenüber GitHub und die nötigen Werkzeuge."
for tool in git gh jq docker cargo ssh-keygen shasum; do
  command -v "$tool" >/dev/null || die "$tool fehlt."
done
gh auth status >/dev/null 2>&1 || die "gh ist nicht angemeldet: gh auth login"
docker buildx version >/dev/null 2>&1 || die "docker buildx ist nicht verfügbar (läuft Docker?)."
[[ -f "$KEY" && -f "$KEY.pub" ]] || die "Signierschlüssel $KEY fehlt."
cmp -s "$KEY.pub" release/release.pub || die "$KEY.pub stimmt nicht mit release/release.pub überein."
[[ "$(git config core.hooksPath || true)" == .githooks ]] || { run git config core.hooksPath .githooks; }
[[ "$(git branch --show-current)" == main ]] || die "Nicht auf main. Releases entstehen auf main: git switch main"
run git fetch --quiet --tags origin
behind=$(git rev-list --count HEAD..origin/main)
ahead=$(git rev-list --count origin/main..HEAD)
if (( behind > 0 )); then
  (( ahead == 0 )) || die "main und origin/main sind auseinandergelaufen ($ahead vor, $behind zurück)."
  say "main liegt $behind Commits hinter origin/main."
  confirm "Jetzt mit git pull --ff-only nachziehen?" || die "main ist nicht aktuell."
  run git pull --ff-only --quiet
fi
if [[ -n "$(tracked_changes)" ]]; then
  warn "Nicht committete Änderungen:"; tracked_changes | sed 's/^/    /'
  confirm "Stammen sie aus einem früheren Lauf dieses Wizards (Version, Cargo.lock, Release-Hinweise)?" ||
    die "Erst committen oder verwerfen; der lokale Build muss dem committeten Stand entsprechen."
fi
printf '  %s✓%s Werkzeuge, Schlüssel und main bereit\n' "$GREEN" "$RESET"
pause "Weiter mit Enter"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Version bestimmen"
LAST_TAG=$(git describe --tags --abbrev=0 --match 'v[0-9]*' --exclude 'v*-*' HEAD 2>/dev/null) ||
  die "Kein früheres Release-Tag gefunden."
LAST=${LAST_TAG#v}
say "Letztes Release: $BOLD$LAST_TAG$RESET, Cargo.toml steht auf $(cargo_version)."
say "Seit $LAST_TAG gemergte PRs:"
while read -r sha pr; do
  title=$(gh pr view "$pr" --json title --jq .title 2>/dev/null || git log -1 --format=%s "$sha")
  step "#$pr  $title"
done < <(pr_merges)
direct=$(git log --first-parent --no-merges --format=%s "$LAST_TAG..HEAD" |
  grep -cEv '^chore: (Version [0-9]|signiertes Release-Manifest)' || true)
(( direct > 0 )) && note "dazu $direct Commit(s) direkt auf main"
subjects=$(commit_lines | cut -f1 | awk '!seen[$0]++')
[[ -n "$subjects" ]] || warn "Seit $LAST_TAG gibt es keine Änderungen."
feats=$(grep -cE '^feat(\(|!|:)' <<<"$subjects" || true)
fixes=$(grep -cE '^(fix|perf)(\(|!|:)' <<<"$subjects" || true)
breaking=$(breaking_count)
printf '\n'
say "Gezählt: $breaking nicht abwärtskompatibel, $feats feat, $fixes fix/perf."
AI_BREAKING=""
if ai_ready; then
  say "$MODEL_CHECK prüft API-Diff, Migrationen und PR-Texte auf nicht markierte Brüche …"
  if AI_BREAKING=$(ai_breaking) && [[ "$AI_BREAKING" == BRUCH:* ]]; then
    printf '%s\n' "$AI_BREAKING" | sed 's/^/    /'
    if (( breaking == 0 )) && [[ "$(head -n1 <<<"$AI_BREAKING")" == *ja* ]]; then
      breaking=1; note "Der Vorschlag zählt die Einschätzung von $MODEL_CHECK als Bruch."
    fi
  else
    AI_BREAKING=""; warn "Keine verwertbare Antwort von $MODEL_CHECK; Brüche bitte selbst prüfen."
  fi
else
  note "Ohne Claude-CLI (oder mit RELEASE_AI=0): API-Brüche ohne Markierung bitte selbst erkennen."
fi
SUGGESTED=$(suggest_version "$LAST" "$breaking" "$feats" "$fixes")
note "Regel: in 0.x erhöht ein Bruch die Minor-, alles andere die Patch-Version; ab 1.0 SemVer."
say "Vorschlag: $BOLD$SUGGESTED$RESET"
VERSION=$(_existing VERSION || true)
if [[ -n "$VERSION" ]] && ! git rev-parse -q --verify "refs/tags/v$VERSION" >/dev/null &&
  printf '%s\n%s\n' "$LAST" "$VERSION" | sort -V -C && [[ "$VERSION" != "$LAST" ]]; then
  note "Ein früherer Lauf hat $VERSION gewählt."
else
  VERSION=""
fi
while :; do
  ask VERSION_INPUT "Version (Enter übernimmt ${VERSION:-$SUGGESTED}):" || die "Keine Version gewählt."
  VERSION_INPUT=${VERSION_INPUT:-${VERSION:-$SUGGESTED}}
  if [[ ! "$VERSION_INPUT" =~ $SEMVER ]]; then warn "Keine gültige Version (z. B. 0.6.1)."; continue; fi
  if [[ "$VERSION_INPUT" == "$LAST" ]] || ! printf '%s\n%s\n' "$LAST" "$VERSION_INPUT" | sort -V -C; then
    warn "$VERSION_INPUT ist nicht höher als $LAST."; continue
  fi
  if git rev-parse -q --verify "refs/tags/v$VERSION_INPUT" >/dev/null ||
    [[ -n "$(git ls-remote --tags origin "refs/tags/v$VERSION_INPUT")" ]]; then
    warn "Das Tag v$VERSION_INPUT existiert bereits."; continue
  fi
  break
done
write_env VERSION "$VERSION_INPUT"
NOTES="docs/release-notes/$VERSION.md"
pause "Weiter mit Enter"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Release-Hinweise $VERSION"
if [[ -f "$NOTES" ]] && ! grep -q 'ENTWURF' "$NOTES"; then
  say "$NOTES ist schon fertig."
  confirm "Trotzdem nochmals im Editor öffnen?" && edit_notes "$NOTES"
else
  if [[ ! -f "$NOTES" ]]; then
    draft_notes "$VERSION"
    if ai_ready; then
      say "$MODEL_NOTES formuliert den Entwurf für den Betreiber (dauert etwa eine Minute) …"
      header=$(sed -n '1,/-->/p' "$NOTES")
      if text=$(sed '1,/-->/d' "$NOTES" | ai_notes "$VERSION") && grep -q "^# Version $VERSION" <<<"$text"; then
        printf '%s\n\n%s\n' "${header/aus den Commits/von $MODEL_NOTES aus den Commits und PRs}" \
          "$(sed -n "/^# Version $VERSION/,\$p" <<<"$text" | sed '/^```/d')" > "$NOTES"
        printf '  %s✓%s Entwurf von %s\n' "$GREEN" "$RESET" "$MODEL_NOTES"
      else
        warn "Keine verwertbare Antwort von $MODEL_NOTES; es bleibt der Entwurf aus den Commit-Betreffs."
      fi
    fi
  fi
  say "Entwurf liegt in $BOLD$NOTES$RESET. Fakten prüfen: das Modell kennt nur PR-Texte und Commits."
  step "Für den Betreiber umschreiben: nach Thema gruppieren wie in docs/release-notes/0.6.0.md."
  step "API-Änderungen, Migrationen und „Nicht betroffen“ prüfen."
  step "Den ENTWURF-Kommentar oben löschen, speichern, Editor schliessen."
  pause "Editor öffnen mit Enter"
  edit_notes "$NOTES"
fi
printf '  %s✓%s %s fertig\n' "$GREEN" "$RESET" "$NOTES"
pause "Weiter mit Enter"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Version setzen"
if [[ "$(cargo_version)" == "$VERSION" ]]; then
  say "rust/Cargo.toml steht schon auf $VERSION."
else
  tmp=$(mktemp)
  awk -v v="$VERSION" '
    /^\[/ { inpkg = ($0 == "[workspace.package]") }
    inpkg && /^version = "/ { $0 = "version = \"" v "\"" }
    { print }' rust/Cargo.toml > "$tmp"
  cat "$tmp" > rust/Cargo.toml; rm -f "$tmp"
  [[ "$(cargo_version)" == "$VERSION" ]] || die "Version in rust/Cargo.toml liess sich nicht setzen."
  printf '  %s✓%s rust/Cargo.toml → %s\n' "$GREEN" "$RESET" "$VERSION"
fi
say "Cargo.lock nachführen (nur die eigenen Crates):"
(cd rust && run cargo update --workspace --quiet)
git --no-pager diff --stat -- rust/Cargo.toml rust/Cargo.lock | sed 's/^/  /'
other=$(git diff -U0 -- rust/Cargo.lock | grep -E '^[-+]name = ' | grep -v '"atvprep' || true)
[[ -z "$other" ]] || { warn "Cargo.lock ändert auch fremde Crates:"; printf '%s\n' "$other" | sed 's/^/    /'; confirm "Trotzdem weiter?" || die "Cargo.lock prüfen."; }
pause "Weiter mit Enter"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Prüfen"
say "Läuft ./scripts/check-all.sh (Rust, Frontend, E2E). Das dauert einige Minuten."
pause "Starten mit Enter"
run ./scripts/check-all.sh || die "check-all.sh ist fehlgeschlagen."
printf '\n  %s✓%s Alle Prüfungen grün\n' "$GREEN" "$RESET"
pause "Weiter mit Enter"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Version committen"
git add rust/Cargo.toml rust/Cargo.lock "$NOTES"
if git diff --cached --quiet; then
  say "Version $VERSION ist schon committet."
else
  git --no-pager diff --cached --stat | sed 's/^/  /'
  [[ -z "$(git diff --name-only)" ]] || warn "Weitere Änderungen bleiben unberührt: $(git diff --name-only | tr '\n' ' ')"
  run git commit --quiet -m "chore: Version $VERSION mit Release-Hinweisen"
  printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$(git log -1 --format='%h %s')"
fi
pause "Weiter mit Enter"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Lokal bauen"
BUILD="/private/tmp/atvprep-release-$VERSION"
[[ -z "$(tracked_changes)" ]] || die "Arbeitsbaum nicht sauber; die Action baut nur committeten Quelltext nach."
say "Baut beide Linux-Binaries in $BUILD (der arm64-Build ist langsam)."
if [[ -x "$BUILD/linux-x86_64/atvprep" && -x "$BUILD/linux-aarch64/atvprep" ]] &&
  ! confirm "Dort liegt schon ein Build. Neu bauen? (Nein nur, wenn er vom aktuellen Commit stammt)"; then
  say "Vorhandenen Build verwenden."
else
  rm -rf "$BUILD"
  run ./rust/release/build.sh "$BUILD" || die "Build fehlgeschlagen."
fi
printf '  %s✓%s Binaries in %s\n' "$GREEN" "$RESET" "$BUILD"
pause "Weiter mit Enter"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Manifest erzeugen und signieren"
run ./scripts/make-manifest.sh "$BUILD" | sed "s/^/  /" || die "Manifest liess sich nicht erzeugen."
[[ "$(jq -r .version release/release.json)" == "$VERSION" ]] || die "Manifest nennt nicht Version $VERSION."
say "Signieren mit $KEY (Namespace atvprep-release). ssh-keygen fragt nach der Passphrase."
rm -f release/release.json.sig
run ssh-keygen -Y sign -q -f "$KEY" -n atvprep-release release/release.json || die "Signieren fehlgeschlagen."
signers=$(mktemp)
printf 'atvprep %s\n' "$(cat "$KEY.pub")" > "$signers"
run ssh-keygen -Y verify -f "$signers" -I atvprep -n atvprep-release -s release/release.json.sig < release/release.json |
  sed 's/^/  /' || { rm -f "$signers"; die "Signatur passt nicht zum Schlüssel."; }
rm -f "$signers"
cmp "$KEY.pub" release/release.pub || die "release/release.pub weicht vom Schlüssel ab."
printf '  %s✓%s Signatur geprüft. release/release.json ab jetzt nicht mehr verändern.\n' "$GREEN" "$RESET"
pause "Weiter mit Enter"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Manifest committen"
git add release/release.json release/release.json.sig release/release.pub
if git diff --cached --quiet; then
  say "Das signierte Manifest für $VERSION ist schon committet."
else
  run git commit --quiet -m "chore: signiertes Release-Manifest für $VERSION"
  printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$(git log -1 --format='%h %s')"
fi
note "Die Binaries werden nie committet; die Action baut sie selbst nach."
pause "Weiter mit Enter"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Pushen und taggen"
TAG="v$VERSION"
say "Folgende Commits gehen nach origin/main:"
git --no-pager log --oneline origin/main..HEAD | sed 's/^/    /'
say "Danach wird $BOLD$TAG$RESET auf $(git rev-parse --short HEAD) gesetzt und gepusht; das startet das Release."
warn "Ein veröffentlichtes Release lässt sich nicht ersetzen, nur durch eine höhere Version ablösen."
if [[ -n "$(git ls-remote --tags origin "refs/tags/$TAG")" ]]; then
  say "$TAG liegt schon auf GitHub."
else
  confirm "Jetzt main pushen und $TAG taggen?" || die "Abgebrochen vor dem Push."
  run git push --quiet origin main
  git rev-parse -q --verify "refs/tags/$TAG" >/dev/null || run git tag "$TAG"
  run git push --quiet origin "$TAG"
  printf '  %s✓%s main und %s gepusht\n' "$GREEN" "$RESET" "$TAG"
fi
pause "Weiter mit Enter"

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Action beobachten und Release-Hinweise setzen"
say "Der Job release baut nach, vergleicht mit dem signierten Manifest und veröffentlicht;"
say "danach spiegelt der Job mirror nach Gitea."
run_id=""
for _ in $(seq 1 30); do
  run_id=$(gh run list --workflow release.yml --event push --branch "$TAG" --limit 1 \
    --json databaseId --jq '.[0].databaseId // empty' 2>/dev/null || true)
  [[ -n "$run_id" ]] && break
  sleep 4
done
[[ -n "$run_id" ]] || die "Kein Lauf von release.yml für $TAG gefunden: https://github.com/chLuethy/atvprep-rs/actions"
open_url "https://github.com/chLuethy/atvprep-rs/actions/runs/$run_id"
if ! gh run watch "$run_id" --exit-status --interval 15; then
  warn "Der Lauf ist fehlgeschlagen. Vorgehen: docs/releasing.md, Abschnitt „Wenn etwas schiefgeht“."
  note "Abweichende Hashes: nie mit den Hashes der Action neu signieren. Nur der Spiegel kaputt:"
  note "Workflow von Hand mit mirror_version=$VERSION starten."
  exit 1
fi
have=$(gh release view "$TAG" --json assets --jq '[.assets[].name] | sort | join(" ")')
want=$(printf '%s\n' "${NAMES[@]}" | sort | tr '\n' ' ' | sed 's/ $//')
[[ "$have" == "$want" ]] || die "Release $TAG hat andere Dateien: $have"
printf '  %s✓%s %s veröffentlicht mit %s\n' "$GREEN" "$RESET" "$TAG" "$have"
if confirm "Release-Hinweise aus $NOTES als Text ins GitHub-Release übernehmen?"; then
  run gh release edit "$TAG" --notes-file "$NOTES" >/dev/null
  printf '  %s✓%s Release-Text gesetzt (die signierten Dateien bleiben unverändert)\n' "$GREEN" "$RESET"
fi
open_url "https://github.com/chLuethy/atvprep-rs/releases/tag/$TAG"
open_url "https://git.ch-luethy.ch/chl/atvprep-rs/releases/tag/$TAG"
step "Prüfen, dass beide Seiten die fünf Dateien zeigen."
note "Weiter von Hand (docs/releasing.md 12–13): Einzeiler auf einem Linux-Host testen, dann"
note "im Releasefenster auf mm ausrollen, siehe DEPLOYMENT.md."
pause "Fertig mit Enter"
rm -f "$ENV_FILE"

finish
}

run_wizard "$@"; exit
